import { GameBoard, Piece, initializeBoard, isKingInCheck, isCheckmate, isStalemate, getValidMoves, movePiece } from '../core-engine/core-engine.ts';

export function render(container: HTMLElement) {
  container.innerHTML = `
    <div class="app">
      <h1>3D Chess Game</h1>
      <div class="row">
        <button id="startGameBtn" class="btn btn-primary">Start Game</button>
        <button id="undoMoveBtn" class="btn btn-secondary">Undo Move</button>
        <button id="resetBoardBtn" class="btn btn-secondary">Reset Board</button>
      </div>
      <div class="row">
        <input id="moveInput" type="text" placeholder="Enter move (e.g., e4, Nf3)">
        <button id="makeMoveBtn" class="btn btn-primary">Make Move</button>
      </div>
      <div class="row">
        <div id="statusDisplay" class="status"></div>
      </div>
      <div class="row">
        <div id="moveHistoryDisplay" class="move-history"></div>
      </div>
    </div>
  `;

  const startGameBtn = document.getElementById('startGameBtn') as HTMLButtonElement;
  const undoMoveBtn = document.getElementById('undoMoveBtn') as HTMLButtonElement;
  const resetBoardBtn = document.getElementById('resetBoardBtn') as HTMLButtonElement;
  const moveInput = document.getElementById('moveInput') as HTMLInputElement;
  const makeMoveBtn = document.getElementById('makeMoveBtn') as HTMLButtonElement;
  const statusDisplay = document.getElementById('statusDisplay') as HTMLDivElement;
  const moveHistoryDisplay = document.getElementById('moveHistoryDisplay') as HTMLDivElement;

  let board: GameBoard = initializeBoard();
  let history: string[] = [];
  let currentPlayer: string = 'w';

  function renderBoard() {
    const boardDiv = document.createElement('div');
    boardDiv.style.display = 'grid';
    boardDiv.style.gridTemplateColumns = 'repeat(8, 1fr)';
    boardDiv.style.gridTemplateRows = 'repeat(8, 1fr)';
    boardDiv.style.gap = '1px';
    boardDiv.style.width = '256px';
    boardDiv.style.height = '256px';
    boardDiv.style.backgroundColor = '#272d33';

    for (let row = 0; row < 8; row++) {
      for (let col = 0; col < 8; col++) {
        const cellDiv = document.createElement('div');
        cellDiv.style.width = '32px';
        cellDiv.style.height = '32px';
        cellDiv.style.backgroundColor = (row + col) % 2 === 0 ? '#343a40' : '#444e5c';
        cellDiv.style.display = 'flex';
        cellDiv.style.alignItems = 'center';
        cellDiv.style.justifyContent = 'center';
        cellDiv.style.fontSize = '16px';
        cellDiv.style.color = '#ffffff';
        cellDiv.style.cursor = 'pointer';

        const piece = board.pieces[row][col];
        if (piece) {
          cellDiv.textContent = piece.type;
        }

        cellDiv.addEventListener('click', () => {
          const move = `${String.fromCharCode(97 + col)}${8 - row}`;
          makeMove(move);
        });

        boardDiv.appendChild(cellDiv);
      }
    }

    container.appendChild(boardDiv);
  }

  function startGame() {
    board = initializeBoard();
    history = [];
    currentPlayer = 'w';
    renderBoard();
    updateStatus('White to move');
  }

  function undoMove() {
    if (history.length === 0) {
      updateStatus('No moves to undo');
      return;
    }
    const lastMove = history.pop();
    if (lastMove) {
      const from = parseMove(lastMove);
      const to = { row: from.row + (from.color === 'w' ? -1 : 1), col: from.col };
      movePiece(board, from.row, from.col, to.row, to.col);
      currentPlayer = from.color;
      updateStatus(`${from.color} to move`);
    }
  }

  function resetBoard() {
    board = initializeBoard();
    history = [];
    currentPlayer = 'w';
    renderBoard();
    updateStatus('White to move');
  }

  function makeMove(move: string) {
    const from = parseMove(move);
    if (!from) {
      updateStatus('Invalid move');
      return;
    }

    const to = { row: from.row + (from.color === 'w' ? -1 : 1), col: from.col };
    const validMoves = getValidMoves(board, from.row, from.col);

    if (!validMoves.some(m => m.row === to.row && m.col === to.col)) {
      updateStatus('Invalid move');
      return;
    }

    movePiece(board, from.row, from.col, to.row, to.col);
    history.push(move);
    currentPlayer = from.color === 'w' ? 'b' : 'w';
    updateStatus(`${currentPlayer} to move`);

    if (isCheckmate(board)) {
      updateStatus(`${currentPlayer} wins`);
    } else if (isStalemate(board)) {
      updateStatus('Stalemate');
    }
  }

  function parseMove(move: string): { row: number; col: number; color: string } | null {
    const col = move.charCodeAt(0) - 97;
    const row = 8 - parseInt(move[1], 10);
    if (col < 0 || col > 7 || row < 0 || row > 7) {
      return null;
    }
    const piece = board.pieces[row][col];
    if (!piece) {
      return null;
    }
    return { row, col, color: piece.color };
  }

  function updateStatus(message: string) {
    statusDisplay.textContent = message;
    moveHistoryDisplay.textContent = history.join(', ');
  }

  startGameBtn.addEventListener('click', startGame);
  undoMoveBtn.addEventListener('click', undoMove);
  resetBoardBtn.addEventListener('click', resetBoard);
  makeMoveBtn.addEventListener('click', () => {
    const move = moveInput.value;
    if (move) {
      makeMove(move);
    }
  });
}
