import { GameBoard, Piece, initializeBoard, isKingInCheck, isCheckmate, isStalemate, getValidMoves, movePiece, GameBoard as GameBoardType } from '../core-engine/core-engine.ts';

export interface GameState {
  board: GameBoardType;
  currentPlayer: string;
  isCheckmate: boolean;
  isStalemate: boolean;
  moves: { from: { row: number; col: number }; to: { row: number; col: number } }[];
}

export function processInput(input: string): GameState {
  const board = initializeBoard();
  const moves: { from: { row: number; col: number }; to: { row: number; col: number } }[] = [];
  let currentPlayer = 'w';

  try {
    const lines = input.split('\n');
    for (const line of lines) {
      const match = line.match(/([a-h])([1-8])\s+([a-h])([1-8])/);
      if (!match) {
        throw new Error(`Invalid move format: ${line}`);
      }

      const fromCol = match[1].charCodeAt(0) - 'a'.charCodeAt(0);
      const fromRow = parseInt(match[2], 10) - 1;
      const toCol = match[3].charCodeAt(0) - 'a'.charCodeAt(0);
      const toRow = parseInt(match[4], 10) - 1;

      const validMoves = getValidMoves(board, fromRow, fromCol);
      const isValid = validMoves.some(
        (m) => m.to.row === toRow && m.to.col === toCol
      );
      if (!isValid) {
        throw new Error(`Invalid move: ${line}`);
      }

      board = movePiece(board, fromRow, fromCol, toRow, toCol);
      moves.push({ from: { row: fromRow, col: fromCol }, to: { row: toRow, col: toCol } });
      currentPlayer = currentPlayer === 'w' ? 'b' : 'w';
    }
  } catch (error) {
    return { board, currentPlayer, isCheckmate: false, isStalemate: false, moves };
  }

  const checkmate = isCheckmate(board);
  const stalemate = isStalemate(board);
  return { board, currentPlayer, isCheckmate: checkmate, isStalemate: stalemate, moves };
}
