import { GameState, processInput, GameState { board, currentPlayer, isCheckmate, isStalemate, moves, col, to } from '../core-engine/core-engine.ts';

export interface DataStore {
  saveGame(gameState: GameState): void;
  loadGame(): GameState | null;
  getGameHistory(): GameState[];
}

export class DataStoreImpl implements DataStore {
  private gameHistory: GameState[] = [];

  saveGame(gameState: GameState): void {
    this.gameHistory.push(gameState);
  }

  loadGame(): GameState | null {
    if (this.gameHistory.length === 0) return null;
    return this.gameHistory[this.gameHistory.length - 1];
  }

  getGameHistory(): GameState[] {
    return [...this.gameHistory];
  }
}
